import { agentPalette, type Colors, createColors, palette, tunedAgentPalettes } from "@parity-app/presence-colors"
import { track } from "../../report-error.ts"

/**
 * The window's colors for people and agents on the canvas, handed out by key (PAR-1236). Neither list runs out: past
 * the hand-tuned palettes, more are generated by number, and the first claim to need each one records
 * `colors.generated`. People's palettes are all generated, so theirs count from the first. The multiplayer extension
 * claims people's once it lands (PAR-1233).
 *
 * @public
 */
export const personColors: Colors = createColors({
  palette,
  tuned: 0,
  onGenerated: (n, keys) => track("colors.generated", { list: "people", n, keys })
})

/** Agents' colors: the hand-tuned palettes first, then generated ones. A key is an agent's id. */
export const agentColors: Colors = createColors({
  palette: agentPalette,
  tuned: tunedAgentPalettes.length,
  onGenerated: (n, keys) => track("colors.generated", { list: "agents", n, keys })
})
